    # according to the recurring lane permutation, clearing the left cells.
    for r in range(1, len(grid), 2):
        bits = [grid[r][3 * j + 1] == 0 for j in range(5)]
        for j in range(5):
            out[r][3 * j] = bg
        for j, source in enumerate((3, 4, 1, 0, 2)):
            out[r][3 * j + 1] = 0 if bits[source] else bg
